// Adds a tip to a subtotal. Money is in integer cents; percent is a
// number such as 15 or 12.5. The tip is rounded to the nearest cent
// (a half cent rounds up). A zero tip is allowed; a negative one is not.
function withTip(subtotalCents, percent) {
  if (percent < 0) throw new RangeError('Tip percent cannot be negative');
  const tipCents = Math.round((subtotalCents * percent) / 100);
  return { tipCents, totalCents: subtotalCents + tipCents };
}

