function withTip(subtotalCents, percent) {
  if (percent < 0) throw new RangeError('Tip percent cannot be negative');
  const tipCents = Math.floor((subtotalCents * percent) / 100);
  return { tipCents, totalCents: subtotalCents + tipCents };
}

