describe('withTip', () => {
  test('adds a 15% tip to the subtotal', () => {
    const subtotalCents = 2000;

    const result = withTip(subtotalCents, 15);

    expect(result).toEqual({ tipCents: 300, totalCents: 2300 });
  });

  test('rounds a half-cent tip up to the next cent', () => {
    const result = withTip(1980, 12.5);

    expect(result).toEqual({ tipCents: 248, totalCents: 2228 });
  });

  test('allows a zero tip', () => {
    const result = withTip(2000, 0);

    expect(result).toEqual({ tipCents: 0, totalCents: 2000 });
  });

  test('rejects a negative tip percent', () => {
    expect(() => withTip(2000, -5)).toThrow(RangeError);
  });
});
